<script module lang="ts">
/**
 * Numbered page controls for paged lists (`design/components/pagination.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/pagination.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  PAGINATION_ELLIPSIS,
  agentMember,
  joinSlot,
  paginationWindow,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/pagination.module.css'
import Button from '../controls/Button.svelte'
import Inline from '../layout/Inline.svelte'

export type SiblingCount = NonNullable<PaginationProps['siblingCount']>

export interface PaginationMessages {
  previous: string
  next: string
  page: (page: number) => string
}

export interface PaginationProps {
  /**
   * The app holds the pager while it does something else to the list: every control is disabled,
   * the current page too, and no page is asked for.
   */
  disabled?: boolean
  /**
   * A page's address, such as `?page=3`. Given, each control that goes to another page is a link
   * to that page's address, so a crawler, a new tab and a reader whose script has not loaded can
   * follow it. A click the browser would follow in this tab calls `onPageChange` in place of the
   * navigation; a click with a modifier key opens the address. The current page, a control with
   * nowhere to go and a held pager's controls stay buttons.
   */
  getPageHref?: (page: number) => string
  label?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: PaginationMessages
  onPageChange?: (page: number) => void
  /**
   * 1-based and controlled, because the current page belongs to the list.
   */
  page: number
  pageCount: number
  siblingCount?: 1 | 2
}
</script>

<script lang="ts">
let {
  disabled = false,
  getPageHref,
  label: labelOwn = 'Pagination',
  messages = (() => ({
    previous: 'Previous page',
    next: 'Next page',
    page: (page) => `Page ${page}`,
  }))(),
  onPageChange,
  page,
  pageCount,
  siblingCount = 1,
}: PaginationProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let focused = $state(null as HTMLElement | null)
let focusedControl = $state(null as string | number | null)
let taken = $state(null as string | number | null)
let root = $state<HTMLElement | null>(null)
const entries = $derived(paginationWindow(page, pageCount, siblingCount))
const controls = $derived([
  'previous',
  ...entries.filter((shown) => shown !== PAGINATION_ELLIPSIS),
  'next',
])
const focusIn = $derived((event: FocusEvent) => {
  const target = event.target as HTMLElement
  const pager = root as HTMLElement | null
  const names: readonly (string | number)[] = controls
  const at = pager === null ? -1 : [...pager.querySelectorAll('button, a[href]')].indexOf(target)
  focused = target
  focusedControl = at < 0 ? null : (names[at] ?? null)
})
const focusOut = $derived((event: FocusEvent) => {
  const target = event.target as HTMLElement
  if (target.matches(':disabled')) return
  queueMicrotask(() => {
    if (focused === target && target.isConnected) focused = null
  })
})
const keepPlace = $derived(() => {
  const pager = root as HTMLElement | null
  if (pager === null) return
  const names: readonly (string | number)[] = controls
  const drawn = () => [...pager.querySelectorAll<HTMLElement>('button, a[href]')]
  const onPage = () => document.activeElement === null || document.activeElement === document.body
  const left = focused as HTMLElement | null
  if (left !== null && !left.isConnected) {
    focused = null
    const name = focusedControl
    const now = name === null ? undefined : drawn()[names.indexOf(name)]
    if (now !== undefined && onPage()) {
      if (now.matches(':disabled')) focused = now
      else now.focus()
    }
  }
  if (!disabled) {
    const control = taken
    taken = null
    if (control === null || document.activeElement !== pager) return
    const element = drawn()[names.indexOf(control)]
    if (element !== undefined && !element.matches(':disabled')) element.focus()
    return
  }
  const from = focused as HTMLElement | null
  if (from === null || !from.isConnected || !from.matches(':disabled')) return
  const active = document.activeElement
  if (active !== from && active !== null && active !== document.body) return
  taken = names[drawn().indexOf(from)] ?? null
  pager.focus()
})
const linked = $derived(!disabled && getPageHref !== undefined)
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const follow = $derived((event: MouseEvent, to: number): void => {
  if (!navigatesHere(event)) return
  event.preventDefault()
  onPageChange?.(to)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    keepPlace()
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [root])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['disabled'],
      })
  release1 = () => {
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect1, { watch: () => entries.length > 0 })
onDestroy(() => release1?.())
const effect2 = () => {
  keepPlace()
}
watchEffect(effect2, { watch: () => disabled, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Pagination',
    element: () => root,
    state: () => ({ page: page, 'page-count': pageCount, disabled: disabled }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!Number.isInteger(value) || value < 1 || value > pageCount) {
              throw new Error(`There is no page ${value}; the pages run from 1 to ${pageCount}.`)
            }
            if (value !== page) onPageChange?.(value)
          })(),
      },
    },
    withholds: () => root,
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if entries.length > 0
    }<nav
      bind:this={root}
      class={styles.pagination}
      aria-label={label}
      data-disabled={(disabled) ? '' : undefined}
      tabindex="-1"
      data-member="pagination"
      onfocusin={(event) => { focusIn(event) }}
      onfocusout={(event) => { focusOut(event) }}
      ><Inline gap={1} align="center" wrap={true}
        >{#if linked && page > 1 && page - 1 <= pageCount
          }<a
            class={styles.link}
            href={getPageHref?.(page - 1)}
            aria-label={messages.previous}
            data-variant="ghost"
            data-size="sm"
            data-tone="neutral"
            data-icon-only=""
            onclick={(event) => { follow(event, page - 1) }}
            ><span class={styles.linkGlyph}><Icon name="previous" size="sm" /></span
          ></a
        >{:else
          }<Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="previous"
            label={messages.previous}
            disabled={disabled || page <= 1}
            onClick={() => { onPageChange?.(page - 1) }}
        />{/if
        }{#each entries as entry, at (entry === PAGINATION_ELLIPSIS ? `gap-${at}` : entry)
          }{#if entry === PAGINATION_ELLIPSIS
            }<span class={styles.ellipsis} aria-hidden="true">…</span
          >{:else if linked && entry !== page
            }<a
              class={styles.link}
              href={getPageHref?.(entry)}
              aria-label={messages.page(entry)}
              data-variant="ghost"
              data-size="sm"
              data-tone="neutral"
              onclick={(event) => { follow(event, entry) }}
              ><span class={styles.linkLabel}>{String(entry)}</span
            ></a
          >{:else
            }<Button
              variant={entry === page ? 'soft' : 'ghost'}
              tone={entry === page ? 'accent' : 'neutral'}
              size="sm"
              current={entry === page}
              label={String(entry)}
              aria-label={messages.page(entry)}
              {disabled}
              onClick={() => { if (entry !== page) onPageChange?.(entry) }}
          />{/if
        }{/each
        }{#if linked && page < pageCount && page + 1 >= 1
          }<a
            class={styles.link}
            href={getPageHref?.(page + 1)}
            aria-label={messages.next}
            data-variant="ghost"
            data-size="sm"
            data-tone="neutral"
            data-icon-only=""
            onclick={(event) => { follow(event, page + 1) }}
            ><span class={styles.linkGlyph}><Icon name="next" size="sm" /></span
          ></a
        >{:else
          }<Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="next"
            label={messages.next}
            disabled={disabled || page >= pageCount}
            onClick={() => { onPageChange?.(page + 1) }}
        />{/if
      }</Inline
    ></nav
  >{/if
}{/if
}{@render joined.end?.()}
